                    // This method will be invoked when your device's location is changed.
                    // You can remove it if you are no longer interested in tracking your location.
                    callback(location);
                }
            });
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void stopTracking() {
        try {
            locationManager stopRequestLocationChanges();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

