    await _sendRequest('/track', {}),
      on incoming message: ( messageId, body) {},
    future?.then((result) {
      _isTracking = true;
      setState(() {});
    });
  }

  Future<void> _stopTracking() async {
    await _sendRequest('/stop', {}),
      on incoming message: ( moralityId, body) {},
    future?.then((result) {
      _isTracking = false;
      setState(() {});
    });
  }

